"""
Deep health check endpoint.

Probes all external services configured via env vars and returns their
connectivity status. Services that are not configured are omitted from
the response.

GET /health/deep
Response: {"status": "ok"|"degraded"|"down", "services": {"<name>": "<status>"}}
"""

import asyncio
import os
from urllib.parse import urlparse, urlunparse

import httpx
from fastapi import APIRouter

router = APIRouter(tags=["health"])

_PROBE_TIMEOUT = httpx.Timeout(5.0, connect=3.0)


def _base_url(url: str) -> str:
    """Strip path/query from a URL so we probe just scheme+host+port."""
    p = urlparse(url)
    return urlunparse((p.scheme, p.netloc, "/", "", "", ""))


async def _probe(url: str) -> str:
    """Attempt a lightweight GET and return 'ok' or 'error:<reason>'."""
    try:
        async with httpx.AsyncClient(timeout=_PROBE_TIMEOUT) as client:
            r = await client.get(url)
        return "ok" if r.status_code < 500 else f"error:http_{r.status_code}"
    except httpx.ConnectError:
        return "error:connection_refused"
    except httpx.TimeoutException:
        return "error:timeout"
    except Exception as exc:
        return f"error:{type(exc).__name__}"


def _configured_services() -> dict:
    """Return {name: probe_url} for every service found in env vars."""
    services: dict = {}

    chat = (os.getenv("CHAT_API_BASE_URL", "") or "").strip().rstrip("/")
    if chat:
        services["chat_api"] = chat + "/"

    openclaw = (os.getenv("OPENCLAW_API_URL", "") or "").strip()
    if openclaw:
        services["openclaw"] = _base_url(openclaw)

    hermes = (os.getenv("HERMES_API_URL", "") or "").strip()
    if hermes:
        services["hermes"] = _base_url(hermes)

    return services


@router.get("/health/deep")
async def health_deep():
    """Probe all configured external services and return aggregated health."""
    targets = _configured_services()

    if not targets:
        return {"status": "ok", "services": {}}

    results = await asyncio.gather(*[_probe(url) for url in targets.values()])
    services = dict(zip(targets.keys(), results))

    ok_count = sum(1 for s in services.values() if s == "ok")
    total = len(services)

    if ok_count == total:
        status = "ok"
    elif ok_count == 0:
        status = "down"
    else:
        status = "degraded"

    return {"status": status, "services": services}

